import fs from 'node:fs';
import path from 'node:path';
import process from 'node:process';
import { spawnSync } from 'node:child_process';

const root = path.resolve(import.meta.dirname, '..');
const target = path.join(root, 'docs', 'maintainer', 'cli-reference.md');
const result = spawnSync(process.execPath, ['harness/plugin/runtime/cli.mjs', '--help'], {
  cwd: root,
  encoding: 'utf-8',
  shell: false,
});
if (result.status !== 0) {
  process.stderr.write(result.stderr || '');
  process.exit(result.status ?? 1);
}
const output = [
  '# CLI Reference',
  '',
  '> Generated by `node bin/generate-cli-reference.mjs`; do not edit command listings by hand.',
  '',
  '```text',
  result.stdout.trimEnd(),
  '```',
  '',
  'Run `enterprise-harness <command> --help` for command-specific arguments.',
  '',
].join('\n');
if (process.argv.includes('--check')) {
  if (!fs.existsSync(target) || fs.readFileSync(target, 'utf-8') !== output) {
    console.error('CLI reference is stale; run node bin/generate-cli-reference.mjs');
    process.exit(1);
  }
} else {
  fs.writeFileSync(target, output, 'utf-8');
  console.log(path.relative(root, target));
}
